{"file_path":"./crypto_square.go","content":"package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plain text (removing spaces and punctuation,
// down-casing letters), arranges it into a rectangle as square as
// possible, and returns the coded text read down the columns, in
// space-separated chunks padded to the rectangle's row length.
func Encode(pt string) string {
	normalized := normalize(pt)
	if normalized == "" {
		return ""
	}

	r, c := rectangleSize(len(normalized))

	rows := make([]string, r)
	for i := 0; i < r; i++ {
		start := i * c
		end := start + c
		if end > len(normalized) {
			end = len(normalized)
		}
		row := normalized[start:end]
		if len(row) < c {
			row += strings.Repeat(" ", c-len(row))
		}
		rows[i] = row
	}

	chunks := make([]string, c)
	for col := 0; col < c; col++ {
		var sb strings.Builder
		for row := 0; row < r; row++ {
			sb.WriteByte(rows[row][col])
		}
		chunks[col] = sb.String()
	}

	return strings.Join(chunks, " ")
}

func normalize(pt string) string {
	var sb strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			sb.WriteRune(unicode.ToLower(r))
		}
	}
	return sb.String()
}

func rectangleSize(length int) (rows, cols int) {
	c := int(math.Ceil(math.Sqrt(float64(length))))
	r := int(math.Ceil(float64(length) / float64(c)))
	return r, c
}
"}

